CREATE TABLE "WorldCategory" (id uuid PRIMARY KEY, slug varchar(80) UNIQUE NOT NULL, name varchar(120) NOT NULL, description varchar(500), "createdAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE "WorldEvent" (id uuid PRIMARY KEY, "categoryId" uuid NOT NULL REFERENCES "WorldCategory"(id) ON DELETE RESTRICT, title varchar(240) NOT NULL, description varchar(4000), "sourceUrl" text, "resolutionCriteria" varchar(4000) NOT NULL, "opensAt" timestamptz(6) NOT NULL, "closesAt" timestamptz(6) NOT NULL, "startsAt" timestamptz(6), status varchar(16) NOT NULL DEFAULT 'PUBLISHED' CHECK (status IN ('DRAFT','PUBLISHED','CLOSED','RESOLVED','CANCELLED','VOID')), "createdById" uuid NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, "createdAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp(), "updatedAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp(), CHECK ("closesAt">"opensAt"));
CREATE TABLE "WorldOpportunity" (id uuid PRIMARY KEY, "eventId" uuid NOT NULL REFERENCES "WorldEvent"(id) ON DELETE RESTRICT, code varchar(64) NOT NULL, label varchar(300) NOT NULL, position int NOT NULL, UNIQUE ("eventId",code), UNIQUE ("eventId",position));
CREATE TABLE "WorldPrediction" (id uuid PRIMARY KEY, "eventId" uuid NOT NULL REFERENCES "WorldEvent"(id) ON DELETE RESTRICT, "opportunityId" uuid NOT NULL REFERENCES "WorldOpportunity"(id) ON DELETE RESTRICT, "predictorId" uuid NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, confidence numeric(8,6) NOT NULL CHECK (confidence>=0 AND confidence<=1), confirmedAt timestamptz(6) NOT NULL, "supersedesId" uuid UNIQUE REFERENCES "WorldPrediction"(id) ON DELETE RESTRICT, "predictedAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp(), "snapshotHash" varchar(64) NOT NULL, createdAt timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE "WorldResolution" (id uuid PRIMARY KEY, "eventId" uuid UNIQUE NOT NULL REFERENCES "WorldEvent"(id) ON DELETE RESTRICT, "outcomeOpportunityId" uuid REFERENCES "WorldOpportunity"(id) ON DELETE RESTRICT, state varchar(16) NOT NULL CHECK (state IN ('TEST','OFFICIAL','CANCELLED','VOID')), rationale varchar(4000) NOT NULL, "resolvedById" uuid NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, "resolvedAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE "WorldComment" (id uuid PRIMARY KEY, "eventId" uuid NOT NULL REFERENCES "WorldEvent"(id) ON DELETE RESTRICT, "authorId" uuid NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, body varchar(2000) NOT NULL, "createdAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp());
CREATE TABLE "WorldReaction" ("eventId" uuid NOT NULL REFERENCES "WorldEvent"(id) ON DELETE RESTRICT, "userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT, kind varchar(32) NOT NULL, "createdAt" timestamptz(6) NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY ("eventId","userId",kind));
CREATE INDEX world_event_calendar ON "WorldEvent" (status,"opensAt","closesAt");
CREATE INDEX world_prediction_actor ON "WorldPrediction" ("predictorId","predictedAt");
CREATE INDEX world_comment_event ON "WorldComment" ("eventId","createdAt");
ALTER TABLE "WorldCategory" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldEvent" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldOpportunity" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldPrediction" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldResolution" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldComment" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorldReaction" ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE ON "WorldCategory","WorldEvent","WorldOpportunity","WorldPrediction","WorldResolution","WorldComment","WorldReaction" TO orvok_app_runtime;
CREATE POLICY world_category_read ON "WorldCategory" FOR SELECT TO orvok_app_runtime USING (true);
CREATE POLICY world_event_read ON "WorldEvent" FOR SELECT TO orvok_app_runtime USING (status IN ('PUBLISHED','CLOSED','RESOLVED','CANCELLED','VOID') OR "createdById"=orvok_current_actor());
CREATE POLICY world_event_write ON "WorldEvent" FOR INSERT TO orvok_app_runtime WITH CHECK ("createdById"=orvok_current_actor() AND EXISTS (SELECT 1 FROM "User" WHERE id=orvok_current_actor() AND role IN ('ADMIN','MODERATOR')));
CREATE POLICY world_event_update ON "WorldEvent" FOR UPDATE TO orvok_app_runtime USING (EXISTS (SELECT 1 FROM "User" WHERE id=orvok_current_actor() AND role IN ('ADMIN','MODERATOR'))) WITH CHECK (EXISTS (SELECT 1 FROM "User" WHERE id=orvok_current_actor() AND role IN ('ADMIN','MODERATOR')));
CREATE POLICY world_opportunity_read ON "WorldOpportunity" FOR SELECT TO orvok_app_runtime USING (EXISTS (SELECT 1 FROM "WorldEvent" e WHERE e.id="eventId"));
CREATE POLICY world_opportunity_write ON "WorldOpportunity" FOR INSERT TO orvok_app_runtime WITH CHECK (EXISTS (SELECT 1 FROM "WorldEvent" e WHERE e.id="eventId" AND e."createdById"=orvok_current_actor()));
CREATE POLICY world_prediction_owner ON "WorldPrediction" FOR SELECT TO orvok_app_runtime USING ("predictorId"=orvok_current_actor() OR EXISTS (SELECT 1 FROM "WorldEvent" e WHERE e.id="eventId" AND e.status IN ('CLOSED','RESOLVED','CANCELLED','VOID')));
CREATE POLICY world_prediction_insert ON "WorldPrediction" FOR INSERT TO orvok_app_runtime WITH CHECK ("predictorId"=orvok_current_actor());
CREATE POLICY world_resolution_admin ON "WorldResolution" FOR SELECT TO orvok_app_runtime USING (true);
CREATE POLICY world_resolution_insert ON "WorldResolution" FOR INSERT TO orvok_app_runtime WITH CHECK ("resolvedById"=orvok_current_actor() AND EXISTS (SELECT 1 FROM "User" WHERE id=orvok_current_actor() AND role IN ('ADMIN','MODERATOR')));
CREATE POLICY world_comment_access ON "WorldComment" FOR ALL TO orvok_app_runtime USING ("authorId"=orvok_current_actor() OR EXISTS (SELECT 1 FROM "WorldEvent" e WHERE e.id="eventId" AND e.status IN ('PUBLISHED','CLOSED','RESOLVED'))) WITH CHECK ("authorId"=orvok_current_actor());
CREATE POLICY world_reaction_access ON "WorldReaction" FOR ALL TO orvok_app_runtime USING ("userId"=orvok_current_actor() OR EXISTS (SELECT 1 FROM "WorldEvent" e WHERE e.id="eventId" AND e.status IN ('PUBLISHED','CLOSED','RESOLVED'))) WITH CHECK ("userId"=orvok_current_actor());
CREATE OR REPLACE FUNCTION orvok_world_close_due() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE n integer; BEGIN UPDATE public."WorldEvent" SET status='CLOSED',"updatedAt"=clock_timestamp() WHERE status='PUBLISHED' AND "closesAt"<=clock_timestamp() RETURNING 1 INTO n; RETURN COALESCE(n,0); END $$;
REVOKE ALL ON FUNCTION orvok_world_close_due() FROM PUBLIC; GRANT EXECUTE ON FUNCTION orvok_world_close_due() TO orvok_app_runtime;
CREATE OR REPLACE FUNCTION orvok_world_prediction_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE e public."WorldEvent"; BEGIN SELECT * INTO e FROM public."WorldEvent" WHERE id=NEW."eventId" FOR UPDATE; IF e.status<>'PUBLISHED' OR clock_timestamp() < e."opensAt" OR clock_timestamp() >= e."closesAt" - interval '10 minutes' THEN RAISE EXCEPTION 'world event is not accepting predictions' USING ERRCODE='23514'; END IF; IF NEW."confirmedAt" < NEW."predictedAt" THEN RAISE EXCEPTION 'confirmation must follow prediction' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER world_prediction_guard BEFORE INSERT OR UPDATE ON "WorldPrediction" FOR EACH ROW EXECUTE FUNCTION orvok_world_prediction_guard();
CREATE OR REPLACE FUNCTION orvok_world_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable world snapshot' USING ERRCODE='23514'; END $$;
CREATE TRIGGER world_prediction_immutable BEFORE UPDATE OR DELETE ON "WorldPrediction" FOR EACH ROW EXECUTE FUNCTION orvok_world_immutable();
